<script setup>
import { ref } from 'vue'
import BaseIcon from './BaseIcon.vue'
import { recommendPlaces } from '@/services/aiReadyMock.js'
defineProps({ open:{type:Boolean,default:false} })
const emit=defineEmits(['close'])
const query=ref('오늘 인사동 갈 건데 3곳 정도 추천해줘'),loading=ref(false),result=ref(null)
const photos=['/samples/window.jpg','/samples/salad.jpg','/samples/pasta.jpg']
async function submit(){loading.value=true;try{result.value=await recommendPlaces(query.value)}finally{loading.value=false}}
</script>

<template>
 <div v-if="open" class="overlay" @click.self="emit('close')"><section class="popup" role="dialog" aria-modal="true" aria-labelledby="recommend-title" data-testid="recommendation-modal">
  <button class="close" aria-label="추천 닫기" @click="emit('close')"><BaseIcon name="close" :size="18"/></button><div class="ribbon">♡ 러비의 추천!</div>
  <h2 id="recommend-title">취향이 비슷한 다른 커플이<br><em>선호하는 맛집을 추천해요!</em></h2><p class="subtitle">우리 커플과 취향이 비슷한 128커플이 좋아한 장소예요 ♡</p>
  <form class="query" @submit.prevent="submit"><input v-model="query" aria-label="추천 질문"><button :disabled="loading">{{loading?'찾는 중…':'추천받기'}}</button></form><p v-if="result&&result.status!=='COMPLETED'" class="notice">{{result.message}}</p>
  <template v-if="result?.status==='COMPLETED'"><h3>♥ 우리 커플과 비슷한 취향</h3><ul class="taste"><li>✓ 분위기 좋은 곳</li><li>✓ 파스타 좋아해요</li><li>✓ 카페 데이트 선호</li><li>✓ 사진 잘 나오는 곳</li></ul><h3>♥ 추천 맛집 TOP 3</h3>
   <ol class="cards"><li v-for="(place,index) in result.places" :key="place.placeId" class="card" :data-testid="`recommendation-${place.placeId}`"><span class="rank">{{index+1}}</span><span class="percent">{{98-index*3}}%<small>일치</small></span><img :src="photos[index]" :alt="`${place.name} 대표 이미지`"><div><h4>{{place.name}}</h4><p class="meta">{{place.category}} · 서울 {{index===0?'강남구':index===1?'마포구':'용산구'}}</p><p>{{place.reason}}</p><ul><li v-for="tag in place.matchedTags" :key="tag">#{{tag}}</li></ul><footer><span>♥ {{128-index*32}}커플 추천</span><strong>★ {{place.score}}</strong></footer><small>{{place.basis==='OWN'?'우리 기록':'다른 커플 기록'}}</small></div></li></ol>
   <div class="more"><span>👥</span><div><strong>이 외에도 23개의 맛집이 더 있어요!</strong><p>지금 바로 확인하고 우리만의 맛집 리스트를 만들어보세요.</p></div><button aria-label="전체 추천 장소 보기">→</button></div>
  </template><label class="today"><input type="checkbox"> 오늘 하루 보지 않기</label><button class="confirm" @click="emit('close')">확인했어요!</button>
 </section></div>
</template>

